"""
ebook_fix.extra_partial

Finds the parts of a page that are an advertisement while the rest of the
page is real content: a one-line promotion at the bottom of a copyright page
or of the last chapter ("A free ebook from http://manybooks.net/",
"Generated by ABC Amber LIT Converter, http://www.processtext.com"), and a
picture that is an ad (a "Buy at Amazon" button, a file named advert1.jpg).
Step 4 of docs/backmatter_cleanup_plan.md.

Describes only. Nothing here changes a book; modules/extra_content_removal.py
decides what to do with what is found, the same split the other analysis
modules use.

What is deliberately NOT treated as an ad
------------------------------------------
- A picture whose alt text is just a web address. Omnibus-Tarzan.epub has
  about 40 of them: they are the original magazine cover illustrations, with
  the address they were copied from as alt text. Only evidence that the
  picture is selling something counts (see ad_picture_reason).
- A line that is part of the copyright notice (permissions, rights, ISBN,
  licensing, bulk sales), even when it holds a web address.
- Project Gutenberg's own boilerplate, which has its own module.
- Anything long. An ad line is a sentence or two.
"""

from __future__ import annotations

import posixpath
import re
from urllib.parse import urlparse

from lxml import etree

from ebook_fix.frontmatter import (
    _AD_STRONG,
    _NEWSLETTER_ACTION_RE,
    _NEWSLETTER_TOPIC_RE,
)

XLINK_HREF = "{http://www.w3.org/1999/xlink}href"

# A line of the page counts only when it is among the last few blocks of
# the page: that is where a promotion is added after the real content.
TAIL_BLOCKS = 6
MAX_LINE_WORDS = 40

_BLOCKS = {
    "p", "div", "h1", "h2", "h3", "h4", "h5", "h6", "li", "blockquote",
    "section", "td", "pre", "ul", "ol", "table", "dd", "dt",
}

_URL = re.compile(
    r"https?://|\bwww\.|\b[a-z0-9-]{2,}\.(?:com|net|org|info|io|me|ca|co\.uk|com\.au)\b",
    re.IGNORECASE,
)
_RETAILER = re.compile(
    r"\b(?:amazon|barnes\s*&\s*noble|barnesandnoble|kobo|apple books|ibooks|google play|smashwords|bookbub|audible|itunes)\b",
    re.IGNORECASE,
)

# Wording that sites and converters leave behind on a book they touched.
_SITE_PROMO = tuple(re.compile(p, re.IGNORECASE) for p in (
    r"\bfree e-?books? (?:from|at|by)\b",
    r"\bdownload(?:ed)? (?:this |more |your |free )*(?:e-?)?books? (?:from|at)\b",
    r"\bget (?:more |your )(?:free )?(?:e-?)?books? (?:at|from)\b",
    r"\b(?:this )?e-?book (?:was )?(?:downloaded|obtained|provided|distributed) (?:from|by|at)\b",
    r"\bgenerated by [^.]{0,40}\bconvert(?:er|or)\b",
    r"\b(?:converted|distributed|brought to you) (?:by|at|from) [^.]{0,40}(?:\.com|\.net|\.org|www\.)",
))

# Lines that look like promotion but belong to the book's own notices.
_NOT_AN_AD = re.compile(
    r"permission|copyright|©|\bisbn\b|all rights|reproduc|licen[sc]|liabilit|"
    r"customer service|special (?:sales|discounts)|bulk|gutenberg|\bpublished by\b|"
    r"library of congress|printed in",
    re.IGNORECASE,
)

# Picture evidence. File name tokens that mean advertising (split on
# anything that is not a letter, so "road" and "bad" do not match "ad").
_AD_FILE_TOKENS = {"ad", "ads", "advert", "adverts", "advertisement", "promo", "promotion", "sponsor", "sponsored", "adcard"}
_RETAILER_HOSTS = (
    "amazon.", "barnesandnoble.", "kobo.", "books.apple.", "itunes.apple.", "play.google.",
    "smashwords.", "audible.",
)
# Wording of a button that sells the book ("Buy on Amazon", "Order now").
_BUY_WORDS = re.compile(
    r"\b(?:buy|order|pre-?order|shop|purchase|get (?:it|your copy)|available (?:now|at|on|from))\b",
    re.IGNORECASE,
)
_COVER_NAME = re.compile(r"cover", re.IGNORECASE)


def _local(el) -> str:
    return etree.QName(el).localname.lower() if isinstance(el.tag, str) else ""


def _text(el) -> str:
    return " ".join("".join(el.itertext()).split())


def leaf_blocks(document) -> list:
    """Block elements of the page body that hold no other block element,
    in reading order (a paragraph, a heading, a list item)."""
    bodies = [el for el in document.iter() if isinstance(el.tag, str) and _local(el) == "body"]
    if not bodies:
        return []
    found = []
    for el in bodies[0].iter():
        if not isinstance(el.tag, str) or _local(el) not in _BLOCKS:
            continue
        if any(isinstance(c.tag, str) and _local(c) in _BLOCKS for c in el.iterdescendants()):
            continue
        found.append(el)
    return found


def ad_line_reason(text: str) -> str:
    """Why this block of text is an advertisement line, or "" when it is
    not one. High confidence only: a short block that carries a web address
    or a retailer name together with selling or site-promotion wording."""
    flat = " ".join(text.split())
    words = len(flat.split())
    if not flat or words > MAX_LINE_WORDS or _NOT_AN_AD.search(flat):
        return ""
    lower = flat.lower()
    has_address = bool(_URL.search(flat) or _RETAILER.search(flat))
    if not has_address:
        return ""
    if any(p.search(lower) for p in _SITE_PROMO):
        return "a short line promoting a web site or converter"
    if any(p.search(lower) for p in _AD_STRONG):
        return "a short line with selling wording and a web address"
    if _NEWSLETTER_TOPIC_RE.search(lower) and _NEWSLETTER_ACTION_RE.search(lower):
        return "a short line asking the reader to sign up to a newsletter"
    return ""


def find_ad_lines(document) -> list:
    """[(element, text, reason)] for ad lines among the last blocks of the
    page. The page's role (copyright page, last chapter ...) is the
    caller's business."""
    blocks = leaf_blocks(document)
    found = []
    for el in blocks[-TAIL_BLOCKS:]:
        text = _text(el)
        reason = ad_line_reason(text)
        if reason:
            found.append((el, text, reason))
    return found


def _source(el) -> str:
    return el.get("src") or el.get(XLINK_HREF) or ""


def _host(url: str) -> str:
    try:
        return (urlparse(url).netloc or "").lower()
    except ValueError:
        return ""


def ad_picture_reason(el) -> str:
    """Why this <img> (or SVG <image>) is an advertisement, or "" when
    there is no evidence that it is. The evidence is: a file name that says
    advertisement or promotion, alt text with selling wording, or a button
    that says to buy the book from a retailer. A web address in the alt text is not
    evidence (see the module note). A cover is never an ad."""
    src = _source(el)
    if not src or _COVER_NAME.search(posixpath.basename(src)):
        return ""
    stem = posixpath.splitext(posixpath.basename(src))[0].lower()
    if set(re.findall(r"[a-z]+", stem)) & _AD_FILE_TOKENS:
        return "the picture's file name says it is an advertisement"
    alt = " ".join((el.get("alt") or el.get("title") or "").split()).lower()
    if alt and any(p.search(alt) for p in _AD_STRONG):
        return "the picture's description has selling wording"
    # A "Buy on Amazon" style button: buying wording together with a
    # retailer, named in the picture's description or file name or linked to.
    # A link to a retailer or a social site alone is not enough: an author's
    # own profile icons (BookBub, Amazon author page) look the same.
    if _BUY_WORDS.search(alt) or _BUY_WORDS.search(stem):
        link = el.getparent()
        while link is not None and _local(link) != "a":
            link = link.getparent()
        target = (link.get("href") or "").lower() if link is not None else ""
        retailer = (
            _RETAILER.search(alt) or _RETAILER.search(stem)
            or (target.startswith(("http://", "https://")) and any(h in _host(target) for h in _RETAILER_HOSTS))
        )
        if retailer:
            return "the picture is a button to buy the book from a retailer"
    return ""


def pictures(document) -> list:
    return [
        el for el in document.iter()
        if isinstance(el.tag, str) and _local(el) in ("img", "image") and _source(el)
    ]


def find_ad_pictures(document) -> list:
    """[(element, source, reason)] for every picture on the page that is
    an advertisement."""
    found = []
    for el in pictures(document):
        reason = ad_picture_reason(el)
        if reason:
            found.append((el, _source(el), reason))
    return found


def ad_picture_page_reason(chapter) -> str:
    """Why the whole page is a picture advertisement ("" when it is not):
    no more than a few words of text, and every picture on it is an ad.
    Used to label such a page as an advertisement."""
    document = chapter.document
    if document is None:
        return ""
    if len(" ".join("".join(el.itertext()) for el in document.iter() if isinstance(el.tag, str) and _local(el) == "body").split()) > 3:
        return ""
    shown = pictures(document)
    if not shown:
        return ""
    reasons = [ad_picture_reason(el) for el in shown]
    if all(reasons):
        return "the page is only a picture, and " + reasons[0]
    return ""
